import{c as a,Q as t,j as r,m as n}from"./chunks/framework.W-g_WCNV.js";const u=JSON.parse('{"title":"User registration","description":"","frontmatter":{},"headers":[],"relativePath":"admin/registration.md","filePath":"admin/registration.md"}'),o={name:"admin/registration.md"};function i(s,e,d,l,p,c){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="user-registration" tabindex="-1">User registration <a class="header-anchor" href="#user-registration" aria-label="Permalink to &quot;User registration&quot;">​</a></h1><p>GateKeeper supports four registration modes. The default is <strong>disabled</strong> - only admins can create accounts. Change the mode in <strong>Admin - Settings - Registration</strong>.</p><h2 id="modes" tabindex="-1">Modes <a class="header-anchor" href="#modes" aria-label="Permalink to &quot;Modes&quot;">​</a></h2><h3 id="disabled-default" tabindex="-1">Disabled (default) <a class="header-anchor" href="#disabled-default" aria-label="Permalink to &quot;Disabled (default)&quot;">​</a></h3><p>The <code>/register</code> page returns a 404. Only admins can create accounts from the Users page. Invite links still work regardless of this setting.</p><h3 id="invite-only" tabindex="-1">Invite only <a class="header-anchor" href="#invite-only" aria-label="Permalink to &quot;Invite only&quot;">​</a></h3><p>No self-registration form is shown. Users can only register by following an invite link created by an admin. See <a href="/admin/invites.html">Invite links</a>.</p><h3 id="open" tabindex="-1">Open <a class="header-anchor" href="#open" aria-label="Permalink to &quot;Open&quot;">​</a></h3><p>Anyone can create an account at <code>/register</code>. A &quot;Create account&quot; link appears on the sign-in page. Accounts are active immediately after registration.</p><h3 id="approval-required" tabindex="-1">Approval required <a class="header-anchor" href="#approval-required" aria-label="Permalink to &quot;Approval required&quot;">​</a></h3><p>Anyone can submit a registration request at <code>/register</code>. Accounts are created in a pending state and disabled until an admin approves them. A &quot;Pending approval&quot; banner appears at the top of the Users page when requests are waiting.</p><h2 id="allowed-domains" tabindex="-1">Allowed domains <a class="header-anchor" href="#allowed-domains" aria-label="Permalink to &quot;Allowed domains&quot;">​</a></h2><p>The <strong>Allowed domains for registration</strong> field restricts which email addresses can self-register. Enter one or more domains separated by commas:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>example.com, company.org</span></span></code></pre></div><p>Leave blank to allow any domain. This setting only applies to open and approval modes - it has no effect on invite links, which bypass the domain check.</p><h2 id="approval-queue" tabindex="-1">Approval queue <a class="header-anchor" href="#approval-queue" aria-label="Permalink to &quot;Approval queue&quot;">​</a></h2><p>When using approval mode, pending requests appear at the top of the Users page. For each request you can:</p><ul><li><strong>Approve</strong> - activates the account. The user can then sign in immediately.</li><li><strong>Reject</strong> - deletes the account request permanently.</li></ul><h2 id="audit-log" tabindex="-1">Audit log <a class="header-anchor" href="#audit-log" aria-label="Permalink to &quot;Audit log&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Event</th><th>When</th></tr></thead><tbody><tr><td><code>user.registered</code></td><td>A user submitted a registration form.</td></tr><tr><td><code>user.approved</code></td><td>An admin approved a pending account.</td></tr><tr><td><code>user.rejected</code></td><td>An admin rejected a pending account.</td></tr></tbody></table>',20)])])}const m=a(o,[["render",i]]);export{u as __pageData,m as default};
